const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Define Saskatchewan geometry
  const saskatchewan = ee.FeatureCollection('TIGER/2016/States')
    .filter(ee.Filter.eq('NAME', 'Saskatchewan'));

  // If TIGER doesn't have Saskatchewan, use a simple bounding box
  // Saskatchewan approximate bounds: -110 to -102 longitude, 49 to 60 latitude
  const saskGeometry = ee.Geometry.Rectangle([-110, 49, -102, 60]);

  // 2. Date range for August 3, 2025
  const startDate = '2025-08-03';
  const endDate = '2025-08-04';

  // 3. Load MODIS active fire data (MOD14A1 - 1km thermal anomalies)
  const modisCollection = ee.ImageCollection('MODIS/006/MOD14A1')
    .filterDate(startDate, endDate)
    .filterBounds(saskGeometry);

  const collectionSize = modisCollection.size().getInfo();
  print('MODIS Collection size: ' + collectionSize);

  // Fallback: Try FIRMS data if MODIS unavailable
  let fireCollection = modisCollection;
  if (collectionSize === 0) {
    // Try NASA/FIRMS MODIS active fires
    fireCollection = ee.ImageCollection('NASA/FIRMS/VIIRS_NRT_M6')
      .filterDate(startDate, endDate)
      .filterBounds(saskGeometry);
    const viirsSz = fireCollection.size().getInfo();
    print('VIIRS FIRMS Collection size: ' + viirsSz);
    if (viirsSz === 0) {
      print('No fire data available for August 3, 2025 in Saskatchewan');
      print('C1');
      return;
    }
  }

  // 4. Process: Extract fire pixels (high confidence only)
  // For MOD14A1: band 0 is Fire Mask (0-4 confidence levels)
  const processedFires = fireCollection.map(function(img) {
    // Fire mask: 1=low, 2=medium, 3=high confidence
    const fireMask = img.select('FireMask').gte(2); // High confidence
    return fireMask.selfMask();
  });

  // 5. Count active fires
  const fireCount = processedFires.map(function(img) {
    const count = img.reduceRegion({
      reducer: ee.Reducer.count(),
      geometry: saskGeometry,
      scale: 1000,
      maxPixels: 1e9
    }).get('FireMask');
    return ee.Feature(null, {count: count});
  });

  const countList = fireCount.aggregate_array('count').getInfo();
  print('Fire pixel counts by image: ' + countList);

  const totalFirePixels = fireCollection.aggregate_sum('FireMask_count');

  // Alternative simpler approach: count non-masked pixels
  const firesMosaic = processedFires.mosaic();
  const fireCount2 = firesMosaic.reduceRegion({
    reducer: ee.Reducer.count(),
    geometry: saskGeometry,
    scale: 1000,
    maxPixels: 1e9
  }).getInfo();

  print('Aggregated fire detection: ' + JSON.stringify(fireCount2));

  const totalFires = fireCount2.FireMask !== undefined ? fireCount2.FireMask : 0;

  print('Total active fires detected: ' + totalFires);

  // 6. Validation & Answer
  if (totalFires === null || totalFires === undefined) {
    print('C3');
    return;
  }

  if (totalFires === 0 && collectionSize > 0) {
    print('C2');
    return;
  }

  if (totalFires > 120) {
    print('A');
  } else {
    print('B');
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
